sp_widget.client_script:
function graficoWidgetCtrl($scope, $rootScope) {
  var chartRclLinhaWidget = null;

  $scope.anoSelecionadoWidget = "";
  $scope.bimestreSelecionadoWidget = "";

  function carregarDadosWidget() {
    var filtros = {
      ano: $scope.anoSelecionadoWidget || "",
      bimestre: $scope.bimestreSelecionadoWidget || ""
    };

    $scope.server.get(filtros).then(function(response) {
      var dados = response.data.dadosGraficoRCL || [];
      montarGraficoWidget(dados);
    });
  }

  $rootScope.$on('anoSelecionado', function(event, ano) {
    $scope.anoSelecionadoWidget = ano;
    carregarDadosWidget();
  });

  $rootScope.$on('bimestreSelecionadoRcl', function(event, bimestre) {
    $scope.bimestreSelecionadoWidget = bimestre;
    carregarDadosWidget();
  });

  carregarDadosWidget();

  function montarGraficoWidget(listaDados) {
    if (!listaDados || listaDados.length === 0) {
      if (chartRclLinhaWidget) {
        chartRclLinhaWidget.destroy();
        chartRclLinhaWidget = null;
      }
      $scope.exibirGraficoWidget = false;
      $scope.$applyAsync();
      return;
    }

    $scope.exibirGraficoWidget = true;
    $scope.$applyAsync();

    // Ordenar por ano e bimestre
    listaDados.sort(function(a, b) {
      if(a.ano !== b.ano) {
        return a.ano - b.ano;
      } else {
        return (a.bimestre || 0) - (b.bimestre || 0);
      }
    });

    // Labels
    var labels = listaDados.map(function(item) {
      return item.bimestre ? item.ano + " - " + item.bimestre + "º Bimestre" : item.ano.toString();
    });

    var valoresNormais = listaDados.map(function(item) {
      return item.somaRclNormal / 1;
    });

    var valoresAjustados = listaDados.map(function(item) {
      return item.somaRclAjustada / 1;
    });

    var ctx = document.getElementById('graficoRclLinhaWidget').getContext('2d');

    if (chartRclLinhaWidget) {
      chartRclLinhaWidget.destroy();
    }

    // Define o tipo do gráfico: linha se não tem filtro, barra se tem ano (com ou sem bimestre)
    var tipoGrafico = (!$scope.anoSelecionadoWidget && !$scope.bimestreSelecionadoWidget) ? 'line' : 'bar';

    chartRclLinhaWidget = new Chart(ctx, {
      type: tipoGrafico,
      data: {
        labels: labels,
        datasets: [
          {
            label: 'RCL Normal',
            data: valoresNormais,
            borderColor: '#6BB7F0',
            backgroundColor: 'rgba(107, 183, 240, 1)',
            fill: tipoGrafico === 'line' ? false : true,
            tension: tipoGrafico === 'line' ? 0.3 : 0,
            pointRadius: tipoGrafico === 'line' ? 5 : 0,
            pointHoverRadius: tipoGrafico === 'line' ? 7 : 0
          },
          {
            label: 'RCL Ajustada',
            data: valoresAjustados,
            borderColor: '#4A75B1',
            backgroundColor: '#4A75B1',
            fill: tipoGrafico === 'line' ? false : true,
            tension: tipoGrafico === 'line' ? 0.3 : 0,
            pointRadius: tipoGrafico === 'line' ? 5 : 0,
            pointHoverRadius: tipoGrafico === 'line' ? 7 : 0
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          x: {
            title: { display: true, text: 'Ano / Bimestre' },
            offset: true,
            // stacked: false é padrão, pode omitir
          },
          y: {
            beginAtZero: true,
            title: { display: true, text: 'Valor (em R$)' },
            ticks: {
              callback: function(value) {
                return 'R$ ' + value.toLocaleString('pt-BR') + '';
              }
            },
            // stacked: false padrão
          }
        },
        plugins: {
          legend: { position: 'top' },
          tooltip: {
            callbacks: {
              label: function(context) {
                return context.dataset.label + ': R$ ' + context.parsed.y.toLocaleString('pt-BR') + '';
              }
            }
          }
        }
      }
    });
  }
}

sp_widget.css:
canvas {
  display: block;
  margin: 0 auto;
}

h3, div {
 font-family: 'Roboto Flex', sans-serif;
}

/* --- Media Queries para Responsividade --- */

/* Telas Pequenas (Mobile S, M, L - até 767px) */
@media (max-width: 767px) {
  canvas {
    max-width: 90%; /* Ajustar a largura máxima do canvas */
  }
  h3 {
    font-size: 1rem; /* Ajustar o tamanho da fonte do título */
  }
}

/* Tablets (iPad Mini, iPad Air, Surface Duo, Galaxy Z Fold 5 - 768px até 1023px) */
@media (min-width: 768px) and (max-width: 1023px) {
  canvas {
    max-width: 80%;
  }
  h3 {
    font-size: 1.1rem;
  }
}

/* Laptops e Telas Maiores (iPad Pro, Surface Pro 7, Laptops, 4K - 1024px em diante) */
@media (min-width: 1024px) {
  canvas {
    max-width: none;
  }
  h3 {
  }
}

/* Ajustes para o Surface Duo (540x720) */
@media (width: 540px) and (height: 720px) {
    canvas {
        max-width: 95%;
    }
}

/* Ajustes para Galaxy Z Fold 5 (max-width: 350px) */
@media (max-width: 350px) {
    h3 {
        font-size: 0.9rem;
    }
}

sp_widget.script:
(function() {
  input = input || {};

  var anoFiltro = input.ano || "";
  var bimestreFiltro = input.bimestre || "";

  var grRCL = new GlideAggregate('x_sded9_portal_t_0_u_rcl_basica');

  // Buscar anos disponíveis para saber se existe ano anterior
  var anosDisponiveis = [];
  var grAnos = new GlideRecord('x_sded9_portal_t_0_u_rcl_basica');
  grAnos.orderByDesc('u_ano');
  grAnos.query();
  while (grAnos.next()) {
    var anoAtual = parseInt(grAnos.getValue('u_ano'), 10);
    if (anosDisponiveis.indexOf(anoAtual) === -1) {
      anosDisponiveis.push(anoAtual);
    }
  }
  anosDisponiveis.sort();

  var anosParaFiltrar = [];

  if (anoFiltro !== "") {
    var anoSelecionado = parseInt(anoFiltro, 10);
    anosParaFiltrar.push(anoSelecionado);

    var indexAno = anosDisponiveis.indexOf(anoSelecionado);
    if (indexAno > 0) {
      // Ano anterior existe
      anosParaFiltrar.push(anosDisponiveis[indexAno - 1]);
    }
  }

  // Montar a query com OR para os anos (se tiver)
  if (anosParaFiltrar.length > 0) {
    var qc = grRCL.addQuery('u_ano', anosParaFiltrar[0]);
    for (var i = 1; i < anosParaFiltrar.length; i++) {
      qc.addOrCondition('u_ano', anosParaFiltrar[i]);
    }
  }

  if (bimestreFiltro !== "") {
    grRCL.addQuery('u_bimestre', bimestreFiltro);
  }

  grRCL.addAggregate('SUM', 'u_rcl_normal');
  grRCL.addAggregate('SUM', 'u_rcl_ajustada');
  grRCL.groupBy('u_ano');
  if(bimestreFiltro !== "") {
    grRCL.groupBy('u_bimestre');
  }
  grRCL.orderBy('u_ano');
  if(bimestreFiltro !== "") {
    grRCL.orderBy('u_bimestre');
  }
  grRCL.query();

  var listaRCL = [];

  while(grRCL.next()) {
    listaRCL.push({
      ano: parseInt(grRCL.getValue('u_ano'), 10),
      bimestre: bimestreFiltro !== "" ? parseInt(grRCL.getValue('u_bimestre'), 10) : null,
      somaRclNormal: parseFloat(grRCL.getAggregate('SUM', 'u_rcl_normal')) || 0,
      somaRclAjustada: parseFloat(grRCL.getAggregate('SUM', 'u_rcl_ajustada')) || 0
    });
  }

  data.dadosGraficoRCL = listaRCL;
})();
